import 'dart:collection';
import 'package:flutter/material.dart';
import '../core/types.dart';
import '../core/store.dart';
import '../core/calculations.dart';
import '../shared/ui.dart';

Future<Json?> editLine(BuildContext context,LocalStore store,{Json? initial,bool recipe=false})=>showDialog<Json>(context:context,builder:(_)=>_LineDialog(store:store,initial:initial,recipe:recipe));
class _LineDialog extends StatefulWidget{
  final LocalStore store;final Json? initial;final bool recipe;
  const _LineDialog({required this.store,this.initial,required this.recipe});
  @override State<_LineDialog> createState()=>_LineDialogState();
}
class _LineDialogState extends State<_LineDialog>{
  final form=GlobalKey<FormState>();late Json data=widget.initial==null?{'quantity':1,'unit':'kg','buyQuantity':1,'buyUnit':'kg','costType':'Material','food':true}: {...widget.initial!};
  late String selected=str(data['materialId']).isEmpty?'manual':str(data['materialId']);int revision=0;
  void choose(String? id){if(id==null)return;setState((){selected=id;revision++;if(id=='manual'){data={'name':'','quantity':1,'unit':'Pauschale','buyQuantity':1,'buyUnit':'Pauschale','costType':'Sonstiges','food':false};}else{final m=widget.store.materials.where((x)=>x['id']==id).firstOrNull;if(m!=null)data={...materialSnapshot(m,quantity:1,unit:str(m['buyUnit'])),'food':m['food']!=false};}});}
  @override Widget build(BuildContext context){final available=widget.store.materials;final choices=<DropdownMenuItem<String>>[const DropdownMenuItem(value:'manual',child:Text('Freie Eingabe')),for(final m in available)DropdownMenuItem(value:str(m['id']),child:Text('${m['kind']=='meat'?'Fleisch':'Zutat'}: ${nameOf(m)}',overflow:TextOverflow.ellipsis)),if(selected!='manual'&&!available.any((m)=>m['id']==selected))DropdownMenuItem(value:selected,child:Text('${nameOf(data)} (archiviert)'))];
    return AlertDialog(title:Text(widget.recipe?'Rezeptposition':'Kostenposition'),content:SizedBox(width:480,child:Form(key:form,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(isExpanded:true,value:selected,decoration:const InputDecoration(labelText:'Rohstoff / freie Position'),items:choices,onChanged:choose),const SizedBox(height:12),Fields(key:ValueKey(revision),specs:[const FieldSpec('name','Bezeichnung',required:true),if(selected=='manual')... [FieldSpec('costType','Kostenart',choices:costTypes,required:true),const FieldSpec('food','Essbare Rohmasse',check:true)],const FieldSpec('quantity','Benötigte Menge',number:true,required:true,min:0.000001),FieldSpec('unit','Verbrauchseinheit',choices:units,required:true),const FieldSpec('buyQuantity','Einkaufsmenge / Bezug',number:true,required:true,min:0.000001),FieldSpec('buyUnit','Einkaufseinheit',choices:units,required:true),const FieldSpec('buyPrice','Einkaufspreis für Bezugsmenge (€)',number:true,required:true,min:0),if(!widget.recipe)const FieldSpec('batch','Chargennummer / Beleg')],data:data,changed:()=>setState((){})),ValueRow('Kosten',shownMoney(lineCost(data)),strong:true)])))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Abbrechen')),FilledButton(onPressed:(){if(!(form.currentState?.validate()??false))return;if(lineCost(data)==null){toast(context,'Verbrauchs- und Einkaufseinheit müssen kompatibel sein.');return;}Navigator.pop(context,{...data,'materialId':selected=='manual'?null:selected});},child:const Text('Übernehmen'))]);}
}
List<Json> scaledRecipeLines(Json recipe,LocalStore store,double scale,{bool currentPrices=true}) => maps(recipe['lines']).map((line){final current=currentPrices?store.materials.where((m)=>m['id']==line['materialId']).firstOrNull:null;return <String,dynamic>{...line,if(current!=null)...{'buyPrice':current['buyPrice'],'buyQuantity':current['buyQuantity'],'buyUnit':current['buyUnit'],'analysis':map(current['analysis']),'allergens':current['allergens'],'additives':current['additives'],'food':current['food']!=false,'name':current['name'],'grade':current['grade'],'animal':current['animal'],'supplier':current['supplier']},'quantity':n(line['quantity'])*scale};}).toList();
class LinesEditor extends StatelessWidget{
  final List<Json> lines;final LocalStore store;final VoidCallback changed;final bool recipe;
  const LinesEditor({super.key,required this.lines,required this.store,required this.changed,this.recipe=false});
  @override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[if(lines.isEmpty)const Text('Noch keine Positionen hinzugefügt.'),for(var i=0;i<lines.length;i++)ListTile(contentPadding:EdgeInsets.zero,title:Text(nameOf(lines[i])),subtitle:Text('${fmt(n(lines[i]['quantity']))} ${str(lines[i]['unit'])} · ${str(lines[i]['costType'])}${str(lines[i]['grade']).isEmpty?'':' · ${str(lines[i]['grade'])}'}'),leading:Text(shownMoney(lineCost(lines[i])),style:const TextStyle(fontWeight:FontWeight.bold)),onTap:()async{final result=await editLine(context,store,initial:lines[i],recipe:recipe);if(result!=null){lines[i]=result;changed();}},trailing:IconButton(tooltip:'Entfernen',icon:const Icon(Icons.delete_outline),onPressed:(){lines.removeAt(i);changed();})),OutlinedButton.icon(onPressed:()async{final result=await editLine(context,store,recipe:recipe);if(result!=null){lines.add(result);changed();}},icon:const Icon(Icons.add),label:const Text('Position hinzufügen'))]);
}
